tool.command:

  ln -f -s ${input_haddock_wf_data} ${input_haddock_wf_data}_`echo $$`.${input_haddock_wf_data.ext};

  ln -f -s ${haddock_config_path} ${haddock_config_path}_`echo $$`.${haddock_config_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

haddock3_run

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__cfg__dq__:${properties.cfg},__dq__restart_from__dq__:${properties.restart_from},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_haddock_wf_data) != 'None':
    --input_haddock_wf_data ${input_haddock_wf_data}_`echo $$`.${input_haddock_wf_data.ext}
  #end if

  #if str($haddock_config_path) != 'None':
    --haddock_config_path ${haddock_config_path}_`echo $$`.${haddock_config_path.ext}
  #end if


  --output_haddock_wf_data $outname_output_haddock_wf_data
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_haddock_wf_data}_`echo $$`.${input_haddock_wf_data.ext};

  rm -f ${haddock_config_path}_`echo $$`.${haddock_config_path.ext};


  if test -f $outname_output_haddock_wf_data; then mv $outname_output_haddock_wf_data $output_haddock_wf_data; fi;
